def verify_archive(archive, output_dir):
    # // AI generated by: Codex (gpt-6.2-sol)
    # // Prompt: "Move the script to the repo"
    # // Changes: Use the bundled faculty checker by default.
    checker = Path(os.environ.get(
        "IFJ_CHECKER", Path(__file__).with_name("is_it_ok.sh")
    )).expanduser().resolve()
    if not checker.is_file():
        raise ValueError("Set IFJ_CHECKER to the path of the faculty's is_it_ok.sh")

    bash = os.environ.get("IFJ_BASH")
    if not bash and os.name == "nt":
        git = shutil.which("git")
        if git:
            git_bash = Path(git).resolve().parent.parent / "bin" / "bash.exe"
            if git_bash.is_file():
                bash = str(git_bash)
    bash = bash or shutil.which("bash")
    if not bash:
        raise ValueError("Install Bash 4+ (Git Bash on Windows) or set IFJ_BASH")

    subprocess.run([bash, "-c", "(( BASH_VERSINFO[0] >= 4 )) || "
                    "{ echo 'is_it_ok.sh requires Bash 4+; set IFJ_BASH' >&2; exit 2; }; "
                    'exec "$BASH" "$@"', "ifj-checker", checker.as_posix(),
                    archive.resolve().relative_to(output_dir.resolve()).as_posix()],
                   cwd=output_dir, check=True)


